// ─────────────────────────────────────────────────────────────────────────────
// Build Analyst Prompt · prompt analyst_v1.0 ของงานวิจัย (ไม่แก้ข้อความ)
//   + DEMO ADDENDUM ขอ "profile" สำหรับแสดงผลเท่านั้น (ไม่ใช้คำนวณคะแนน)
//   ไม่ส่งคำพ้องและน้ำหนักเข้า prompt (3.5.2)
// ─────────────────────────────────────────────────────────────────────────────
const TEMPLATE = "You are an evidence checker for a research study on resume-based skill-gap analysis.\nYou will receive (1) a target occupation code, (2) a list of occupational requirements from O*NET 31.0, and (3) the text of one resume in which personal data has already been replaced by placeholders such as [EMAIL], [URL], [PHONE] and [ID].\n\nFollow these nine rules exactly.\n1. Judge each requirement separately, using only the resume text provided between the RESUME markers.\n2. Do not infer a skill from a job title, a company name, an institution name, or the number of years of experience.\n3. Choose exactly one status per requirement: \"evidenced\", \"partially\" or \"missing\".\n   - \"evidenced\": the text describes performing the work or applying the knowledge named by the requirement, with a concrete task, tool or result. Merely listing the skill name is not enough.\n   - \"partially\": the text supports only part of the requirement, or mentions it only as a course, a training, or a bare skill name without context of use.\n   - \"missing\": no text in the resume relates to the requirement.\n4. When the status is not \"missing\", copy one contiguous passage from the resume text into \"quote\", character for character, 20 to 300 characters long.\n5. Do not paraphrase, summarise, translate, correct spelling, change capitalisation, or join fragments taken from different places.\n6. If you cannot copy such a passage, answer \"missing\" and leave \"quote\" as an empty string.\n7. Report \"confidence\" as a number from 0 to 1 describing your own certainty. It will not override the text check.\n8. Return one assessment for every requirement listed, using the exact requirement_id values given, and nothing else.\n9. Reply with a single JSON object only, with no text before or after it, in this form:\n{\"schema_version\": \"analyst_v1.0\", \"role_id\": \"<the occupation code>\", \"assessments\": [{\"requirement_id\": \"<id>\", \"status\": \"evidenced|partially|missing\", \"quote\": \"<exact passage or empty>\", \"confidence\": 0.0}]}\n\nOCCUPATION CODE: {{ROLE_ID}}\n\nREQUIREMENTS (JSON):\n{{REQUIREMENTS_JSON}}\n\nRESUME START\n{{RESUME_TEXT}}\nRESUME END\n";
const ADDENDUM = [
  '',
  'DEMO ADDENDUM (display only, never used for scoring):',
  'Add one more top-level field "profile" to the same JSON object:',
  '{"current_role": "<most recent job title exactly as written, or empty>",',
  ' "years_experience": <total years of work experience as a number, or null if unclear>,',
  ' "certifications": ["<each certification or certificate name copied exactly as written in the resume>"],',
  ' "headline_th": "<one Thai sentence (max 160 characters) describing who this candidate is>",',
  ' "summary_th": "<3-4 Thai sentences: main strengths and the most important gaps for the target occupation, based only on the resume>"}',
  'Do not put personal names, emails, phone numbers or URLs in profile. All other rules above still apply.',
].join('\n');

const role = $('Load Role Data (O*NET 31.0)').first().json.role;
const text = $('Clean Text & Mask PII').first().json.text;
const cfg = $('Config & Validate').first().json.cfg;

const reqList = role.requirements.map((r) => ({ requirement_id: r.id, element_name: r.name, element_description: r.desc }));
const prompt = String(TEMPLATE)
  .split('{{ROLE_ID}}').join(role.role_id)
  .split('{{REQUIREMENTS_JSON}}').join(JSON.stringify(reqList, null, 1))
  .split('{{RESUME_TEXT}}').join(text) + '\n' + ADDENDUM;

const generationConfig = { maxOutputTokens: cfg.GEMINI_MAX_OUTPUT_TOKENS, responseMimeType: 'application/json' };
if (cfg.GEMINI_THINKING_LEVEL) generationConfig.thinkingConfig = { thinkingLevel: cfg.GEMINI_THINKING_LEVEL };

return [{
  json: {
    use_gemini: cfg.USE_GEMINI_ANALYST !== false,
    model: cfg.GEMINI_MODEL_ANALYST,
    prompt_version: 'analyst_v1.0+demo_profile',
    prompt_chars: prompt.length,
    gemini_request: { contents: [{ role: 'user', parts: [{ text: prompt }] }], generationConfig },
  },
}];

