  return {
    seq: i + 1, pick_rank: c.rank, id: it.id, type: it.type, title: it.title, provider: it.provider, platform: it.platform,
    url: /^https:\/\/[^\s"'<>]+$/i.test(it.url) ? it.url : '', level: it.level, difficulty: it.difficulty, delivery: it.delivery,
    language: it.language, outcome_th: it.outcome_th, skills: it.skills, hours: c.hk, cost_cat: it.cost_cat, cost_usd: it.cost_usd,
    exam_code: it.exam_code, validity_years: it.validity_years, phase: it.phase, phase_th: PHASE_TH[it.phase] || it.phase,
    portfolio: it.portfolio, verified_on: it.verified_on,
    covers: c.add.sort().map((r) => ({ id: r, name: nameOf[r] })), new_weight: round(c.wsum, 6), d_k: round(c.dk, 8),
    start_week: round(startW, 2), end_week: round(endW, 2),
    start_month: round(startW / cfg.WEEKS_PER_MONTH, 2), end_month: round(endW / cfg.WEEKS_PER_MONTH, 2),
  };
});

// คะแนนคาดการณ์หลังเรียนจบแผน (สมมติว่าช่องว่างที่แผนครอบคลุมกลายเป็น evidenced)
const D = rows.filter((r) => r.status !== 'abstained');
const wD = D.reduce((s, r) => s + r.w, 0);
const after = D.reduce((s, r) => s + r.w * (covered.has(r.id) ? 1 : ({ evidenced: 1, partially: 0.5, missing: 0 })[r.status]), 0);
const withCand = gaps.filter((g) => candByReq[g]);
let notice = '';
if (!gaps.length) notice = 'ไม่พบช่องว่างทักษะจากข้อกำหนดที่ระบบสรุปได้ จึงไม่มีรายการเรียนรู้ในแผน';
else if (!planItems.length) notice = 'ยังไม่มีรายการที่ผ่านการตรวจความเชื่อมโยงและอยู่ภายในเวลาที่จัดสรรได้ ลองเพิ่มชั่วโมงต่อสัปดาห์หรือระยะเวลา';

return [{
  json: {
    ...ev,
    plan: {
      months, hours_per_week: h, mode, Hmax, total_hours: round(cum, 2), utilization: Hmax ? round(cum / Hmax, 4) : null,
      weeks_needed: round(cum / h, 1), n_gaps: gaps.length, n_covered: covered.size,
      gap_coverage: gaps.length ? round(covered.size / gaps.length, 4) : null,
      gap_coverage_with_candidate: withCand.length ? round(covered.size / withCand.length, 4) : null,
      uncovered_no_candidate: gaps.filter((g) => !candByReq[g]).map((r) => ({ id: r, name: nameOf[r] })),
      uncovered_over_capacity: gaps.filter((g) => candByReq[g] && !covered.has(g)).map((r) => ({ id: r, name: nameOf[r] })),
      owned: ownedItems,
      items: planItems,
      n_courses: planItems.filter((p) => p.type === 'course').length,
      n_certs: planItems.filter((p) => p.type === 'certification').length,
      cost_usd: planItems.reduce((s, p) => s + (p.cost_usd || 0), 0),
      projected_readiness_pct: wD ? round((after / wD) * 100, 2) : null,
      notice,
    },
  },
}];

// ─────────────────────────────────────────────────────────────────────────────
// Build Report · รวมผลเป็น JSON เดียวให้หน้าเว็บแสดงผล (ไม่มีการคำนวณใหม่ในหน้าเว็บ)
// ─────────────────────────────────────────────────────────────────────────────
const v = $('Config & Validate').first().json;
const rd = $('Load Role Data (O*NET 31.0)').first().json;
const prep = $('Clean Text & Mask PII').first().json;
const p = $input.first().json;
const role = rd.role;
const R = p.scores.readiness_pct;
const band = R === null ? { key: 'na', th: 'ประเมินไม่ได้' }
  : R >= 75 ? { key: 'high', th: 'พร้อมสูง' }
  : R >= 50 ? { key: 'mid', th: 'ใกล้พร้อม' }
  : { key: 'low', th: 'ต้องพัฒนาเพิ่ม' };

const report = {
  ok: true,
  run_id: v.run_id,
  generated_at: new Date().toISOString(),
  elapsed_ms: Date.now() - new Date(v.received_at).getTime(),
  input: { ...v.input, file_name: v.file.name, file_mime: v.file.mime, file_size: v.file.size },
  role: {
    role_id: role.role_id, label_th: role.label_th, name_th: role.name_th, name_en: role.name_en, soc: role.soc,
    onet_title: role.onet_title, mapping_type: role.mapping_type, mapping_note_th: role.mapping_note_th,
    job_zone: role.job_zone, job_zone_name: role.job_zone_name, description: role.description,
    education_modal: role.education_modal, education_pct: role.education_pct, education: role.education,
    tasks: role.tasks, hot_tech: role.hot_tech, job_titles: role.job_titles, counts: role.counts,
  },
  verdict: band,
  ocr: prep.ocr,
  analyst: p.analyst,
  scores: p.scores,
  guard: p.guard,
  candidate: p.candidate,
  requirements: p.requirements.map(({ desc, ...r }) => ({ ...r, desc })),
  plan: p.plan,
  provenance: {
    onet: rd.data_meta.onet_version, snapshot: rd.data_meta.snapshot_version, corpus: rd.data_meta.corpus_version,
    dataset_sha256: (rd.data_meta.sha256['Data_Set.xlsx'] || '').slice(0, 12),
    policy: rd.data_meta.policy, built_at: rd.data_meta.built_at,
    rules: 'R0 → R2 → R3 (Demo: โมเดลเดียว ไม่มี R1/R4) · θ = ' + v.cfg.THETA,
    note: 'Demo รอบแรกสำหรับคณะกรรมการ · ข้อมูลอ้างอิงเป็นของจริงแบบ hardcode · ไม่บันทึกเรซูเมลงฐานข้อมูล',
  },
};
return [{ json: report }];

// Check PDF · รับไฟล์ PDF ที่หน้าเว็บสร้าง (html2pdf) ก่อนส่งขึ้น Google Drive
const item = $input.first();
const body = (item.json && item.json.body) || {};
const bin = item.binary || {};
const key = bin.pdf ? 'pdf' : Object.keys(bin)[0];
const errors = [];
let size = 0;
if (!key) errors.push('ไม่พบไฟล์ PDF');
else {
  const buf = await this.helpers.getBinaryDataBuffer(0, key);
  size = buf.length;
  if (buf.slice(0, 5).toString('latin1') !== '%PDF-') errors.push('ไฟล์ที่ส่งมาไม่ใช่ PDF');
  if (size > 25 * 1024 * 1024) errors.push('PDF ใหญ่เกิน 25 MB');
}
const safe = (s) => String(s || '').replace(/[\\/:*?"<>|\u0000-\u001f]+/g, '_').slice(0, 120);
const fileName = safe(body.filename) || ('IS68076026_Report_' + new Date().toISOString().slice(0, 10) + '.pdf');
const out = { json: { ok: errors.length === 0, http_status: errors.length ? 400 : 200, errors, file_name: /\.pdf$/i.test(fileName) ? fileName : fileName + '.pdf', size, run_id: safe(body.run_id) } };
if (key) out.binary = { pdf: { ...bin[key], fileName: out.json.file_name, mimeType: 'application/pdf' } };
return [out];

// Drive Result · สรุปผลอัปโหลดให้หน้าเว็บ (สำเร็จ → ลิงก์เปิดไฟล์ · ล้ม → ข้อความที่อ่านเข้าใจ)
const r = $input.first().json || {};
const meta = $('Check PDF').first().json;
if (r.error || !r.id) {
  const msg = String((r.error && (r.error.message || r.error.description)) || r.error || 'ไม่ได้รับ file id จาก Google Drive');
  return [{ json: { ok: false, http_status: 502, errors: ['อัปโหลดขึ้น Google Drive ไม่สำเร็จ: ' + msg.slice(0, 200) + ' — ตรวจ credential "Google Drive OAuth2" และ Folder ID ในโหนด Upload PDF to Drive'] } }];
}
return [{ json: { ok: true, http_status: 200, file_id: r.id, name: r.name || meta.file_name, size: meta.size,
  web_view_link: r.webViewLink || ('https://drive.google.com/file/d/' + r.id + '/view') } }];
